let page = 1;
let isLoading = false;

const getList = () => {
  if (!isLoading) {
    isLoading = true;
    return new Promise((resolve) => {
      $.ajax({
        url: `https://gateway.caixin.com/api/data//cms-data/columnAuthorList?page=${page}&size=20`,
        success(data) {
          page++;
          isLoading = false;
          resolve(data);
        },
      });
    });
  }
  return null;
};

function formatCustomDate(inputDate) {
  var parts = inputDate.split(/[- :]/);
  var dateObj = new Date(parts[0], parts[1] - 1, parts[2], parts[3], parts[4], parts[5]);

  var year = dateObj.getFullYear();
  var month = String(dateObj.getMonth() + 1).padStart(2, '0');
  var day = String(dateObj.getDate()).padStart(2, '0');
  var hours = String(dateObj.getHours()).padStart(2, '0');
  var minutes = String(dateObj.getMinutes()).padStart(2, '0');

  return year + "年" + month + "月" + day + "日 " + hours + ":" + minutes;
}

const template = (item) => {
  return `
  <div class="wirterItem">
  <img class="leftAvatar" src="${item.logo}" onerror="whenError(this)"/>
  <div class="middleDescription">
      <div class="descriptionName">${item.title}</div>
      <div class="descriptionText">
        ${item.summary || ""}
      </div>
    </div>
    <a class="rightEnter" href="${item.url}">进入专栏</a>
  </div>
`;
};

document.getElementById("loadmore").onclick = async () => {
  const data = await getList();
  data.data.list.forEach((element) => {
    $("#loadmore").before(template(element));
  });
  if (data.data.list.length < 20) {
    document.getElementById("loadmore").style.display = "none";
  }
};

const getSearchList = (searchPage, keyword) => {
  return new Promise((resolve) => {
    $.ajax({
      url: `https://gateway.caixin.com/api/data//cms-data/columnAuthorList?page=${searchPage}&size=20&keyword=${keyword}`,
      success(data) {
        resolve(data);
      },
    });
  });
};

const colorRed = () => {
  const value = document.getElementsByClassName("searchInput")[0].value;
  const titles = document.querySelectorAll(".SearchWriterList .descriptionName");

  function hightLightText(value, text) {
    if (value && text) {
      const reg = new RegExp(value, "gi"); // 动态正则表达式
      return text.replace(reg, `<span style="color:red;">${value}</span>`); // 使用replace替换
    }
    return text
  }

  for (let i = 0; i < titles.length; i++) {
    titles[i].innerHTML = hightLightText(value, titles[i].innerHTML);
  }
};

const searchEvent = async () => {
  const wirterList = document.getElementsByClassName("wirterList")[0];
  wirterList.style.display = "none";
  const serachWirterList =
    document.getElementsByClassName("SearchWriterList")[0];
  serachWirterList.style.display = "block";
  const searchTitle = document.getElementsByClassName("searchTitle")[0];
  searchTitle.style.cursor = "pointer";

  searchTitle.innerHTML = "< 返回";
  searchTitle.onclick = () => {
    serachWirterList.style.display = "none";
    wirterList.style.display = "block";
    searchTitle.style.cursor = "unset";
    searchTitle.innerHTML = "专栏作家列表";
    document.getElementsByClassName("searchInput")[0].value = ''
  };

  const value = document.getElementsByClassName("searchInput")[0].value;
  const data = await getSearchList(1, value);

  if(window.gio){
    gio("track", "zhuanlanAuthor_search", {
      ifHasSearchResult_var: data.data.list.length > 0,
      search_keywords_var: value,
      searchType_var: "专栏作家",
    });
  }

  document.getElementsByClassName(
    "SearchWriterList"
  )[0].innerHTML = `<div id="searchLoadmore">加载更多</div>`;
  data.data.list.forEach((element) => {
    $("#searchLoadmore").before(template(element));
  });

  if (data.data.list.length == 0) {
    document.getElementsByClassName(
      "SearchWriterList"
    )[0].innerHTML = `<div style="text-align:center;font-size:16px;margin-top:40px">暂无相关数据</div>`;
  } else {
    let searchPage = 2;
    document.getElementById("searchLoadmore").onclick = async () => {
      const value = document.getElementsByClassName("searchInput")[0].value;
      const data = await getSearchList(searchPage, value);
      searchPage++;
      data.data.list.forEach((element) => {
        $("#searchLoadmore").before(template(element));
      });
      if (data.data.list.length < 20) {
        document.getElementById("searchLoadmore").style.display = "none";
      }
      colorRed()
    };

    if (data.data.list.length < 20) {
      document.getElementById("searchLoadmore").style.display = "none";
    }
  }
  colorRed()
};

document.getElementsByClassName("searchInputBtn")[0].onclick = searchEvent;
$(".searchInput").keydown(function (event) {
  if (event.keyCode == 13) {
    searchEvent();
  }
});

function whenError(ele) {
  ele.src = "//file.caixin.com/webchannel/newBlog/writerlist/avatar.svg";
}

document.getElementById("loadmore").click();
